input.new_string:
export var shadows = {
  card: '1px 1px 0px ' + colors.glassFaint,
  elevated: '0px 2px 0px ' + colors.glassSubtle
}

// ─── 无障碍配置 ────────────────────────────────────────

export var accessibility = {
  highContrast: false,
  largeFont: false,
  fontScaleStep: 0.2,
  minFontScale: 0.8,
  maxFontScale: 1.6
}

// ─── 高对比度颜色（WCAG AA 标准） ───────────────────

export var highContrastColors = {
  textPrimary: '#ffffff',
  textSecondary: '#e0e0e0',
  textTertiary: '#b0b0b0',
  textMuted: '#808080',
  accentGreen: '#00ff99',
  accentRed: '#ff4444',
  accentAmber: '#ffcc00',
  accentBlue: '#00ccff',
  accentPurple: '#cc99ff'
}

// ─── 动画配置 ────────────────────────────────────────

export var animation = {
  fast: 150,
  normal: 300,
  slow: 500,
  easeOut: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  easeIn: 'cubic-bezier(0.55, 0.055, 0.675, 0.19)'
}

// ─── 辅助函数 ────────────────────────────────────────

export function getHighContrastText(primary, secondary, tertiary, muted) {
  if (accessibility.highContrast) {
    return {
      primary: highContrastColors.textPrimary,
      secondary: highContrastColors.textSecondary,
      tertiary: highContrastColors.textTertiary,
      muted: highContrastColors.textMuted
    }
  }
  return {
    primary: primary || colors.textPrimary,
    secondary: secondary || colors.textSecondary,
    tertiary: tertiary || colors.textTertiary,
    muted: muted || colors.textMuted
  }
}

