input.new_string:
  openScenarios() { router.push({ uri: "/pages/scenarios" }) },
  openHistory() { router.push({ uri: "/pages/history" }) },

  // 语音反馈
  speak(text) {
    try { tts.speak({ text: text, locale: 'zh-CN' }) } catch(e) { /* 不支持则跳过 */ }
  },

  // 按钮反馈
  onSosPress() {
    this.sosPressed = true
    try { vibrator.vibrate({ mode: 'short' }) } catch(e) {}
  },

  onSosRelease() {
    this.sosPressed = false
  },

  onNavPress() {
    this.navPressed = true
    try { vibrator.vibrate({ mode: 'short' }) } catch(e) {}
  },

  onNavRelease() {
    this.navPressed = false
  },

  // 手势导航
  onTouchStart(e) {
    this.touchStartX = e.touches[0].clientX
    this.touchStartY = e.touches[0].clientY
  },

  onTouchEnd(e) {
    var deltaX = e.changedTouches[0].clientX - this.touchStartX
    var deltaY = e.changedTouches[0].clientY - this.touchStartY
    // 水平滑动且距离足够
    if (Math.abs(deltaX) > 50 && Math.abs(deltaX) > Math.abs(deltaY)) {
      if (deltaX < 0) {
        // 左滑 - 进入场景测试
        this.openScenarios()
      } else {
        // 右滑 - 进入事件历史
        this.openHistory()
      }
    }
  }
}

