vibrate() { try { vibrator.vibrate({ mode: "long" }) } catch (e) { /* skip */ } },

startCountdown() {
  var page = this
  this.stopCountdown()
  this.timer = setInterval(function() {
    page.countdown -= 1
    // 更新环形进度
    var pct = (page.totalCountdown - page.countdown) / page.totalCountdown
    page.ringRotation = -90 + Math.round(pct * 360)
    // 最后 3 秒变色
    if (page.countdown <= 3) { page.ringColor = '#ff3a2a' }
    if (page.countdown <= 0) { page.resolve("timeout") }
  }, 1000)
},

input.new_string:
vibrate() { try { vibrator.vibrate({ mode: "long" }) } catch (e) { /* skip */ } },

// 语音反馈
speak(text) {
  try { tts.speak({ text: text, locale: 'zh-CN' }) } catch(e) { /* 不支持则跳过 */ }
},

startCountdown() {
  var page = this
  this.stopCountdown()
  // 初始语音提示
  this.speak('请确认您的安全状态')
  this.timer = setInterval(function() {
    page.countdown -= 1
    // 更新环形进度
    var pct = (page.totalCountdown - page.countdown) / page.totalCountdown
    page.ringRotation = -90 + Math.round(pct * 360)
    // 最后 3 秒变色并语音提示
    if (page.countdown <= 3) {
      page.ringColor = '#ff3a2a'
      page.speak(String(page.countdown))
    }
    if (page.countdown <= 0) {
      page.speak('已超时，正在发送求助')
      page.resolve("timeout")
    }
  }, 1000)
},

openAlert(a) { this.$app.$def.setCurrentAlert(a); router.push({ uri: "/pages/alert" }) },
triggerSos() {
  this.speak('已触发紧急求助')
  this.openAlert(createSosAlert())
},
triggerSosLong() {
  this.speak('已触发紧急求助')
  this.openAlert(createSosAlert())
},

