// ─── User font scale multiplier ───
// Reads from storage and returns a multiplier (0.8 to 1.6)
// This should be called at app init to set the global scale
let _userFontScale = 1.0

export function setUserFontScale(scale) {
  _userFontScale = scale
}

export function getUserFontScale() {
  return _userFontScale
}

// Enhanced fs() that applies user font scale
export function fsUser(baseSize) {
  return Math.round(fs(baseSize) * _userFontScale)
}

